if __name__ == "__main__":
    t = text()
    if "--check" in sys.argv:
        ok = os.path.exists(OUT) and open(OUT, encoding="utf-8").read() == t
        print("build_sop_v4: " + ("ok" if ok else "REFUSED: MethylPhys_CPG_SOP_v4.md differs from the chain's files (run python3 Biological_Physics/MethylPhys/sop/build_sop_v4.py)")); sys.exit(0 if ok else 1)
    open(OUT, "w", encoding="utf-8").write(t); print("build_sop_v4: written", len(t.splitlines()), "lines")
